CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(80) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, full_name VARCHAR(120) NOT NULL, role VARCHAR(30) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL);
CREATE TABLE patients (id BIGINT PRIMARY KEY AUTO_INCREMENT, number VARCHAR(30) NOT NULL UNIQUE, full_name VARCHAR(120) NOT NULL, birth_date DATE, sex VARCHAR(15), phone VARCHAR(30), address VARCHAR(255), allergies TEXT, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX idx_patients_name(full_name));
CREATE TABLE appointments (id BIGINT PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT NOT NULL, doctor_id BIGINT, scheduled_at DATETIME(6) NOT NULL, reason VARCHAR(500), status VARCHAR(20) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, FOREIGN KEY(patient_id) REFERENCES patients(id), FOREIGN KEY(doctor_id) REFERENCES users(id), INDEX idx_appt_time(scheduled_at));
CREATE TABLE visits (id BIGINT PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT NOT NULL, clinician_id BIGINT, appointment_id BIGINT UNIQUE, status VARCHAR(20) NOT NULL, complaint TEXT, history TEXT, examination TEXT, diagnosis TEXT, treatment TEXT, systolic INT, diastolic INT, pulse INT, temperature DECIMAL(4,1), weight_kg DECIMAL(5,1), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, FOREIGN KEY(patient_id) REFERENCES patients(id), FOREIGN KEY(clinician_id) REFERENCES users(id), FOREIGN KEY(appointment_id) REFERENCES appointments(id), INDEX idx_visits_queue(status,created_at));
CREATE TABLE lab_orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, visit_id BIGINT NOT NULL, test_name VARCHAR(120) NOT NULL, result_text TEXT, status VARCHAR(20) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, FOREIGN KEY(visit_id) REFERENCES visits(id));
CREATE TABLE medicines (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL UNIQUE, unit VARCHAR(30) NOT NULL, stock INT NOT NULL, reorder_level INT NOT NULL, unit_price DECIMAL(12,2) NOT NULL, expiry_date DATE, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL);
CREATE TABLE prescriptions (id BIGINT PRIMARY KEY AUTO_INCREMENT, visit_id BIGINT NOT NULL, medicine_id BIGINT NOT NULL, quantity INT NOT NULL, instructions VARCHAR(500), dispensed BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, FOREIGN KEY(visit_id) REFERENCES visits(id), FOREIGN KEY(medicine_id) REFERENCES medicines(id));
CREATE TABLE invoices (id BIGINT PRIMARY KEY AUTO_INCREMENT, visit_id BIGINT NOT NULL UNIQUE, amount DECIMAL(12,2) NOT NULL, description VARCHAR(500) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, FOREIGN KEY(visit_id) REFERENCES visits(id));
CREATE TABLE payments (id BIGINT PRIMARY KEY AUTO_INCREMENT, invoice_id BIGINT NOT NULL, amount DECIMAL(12,2) NOT NULL, method VARCHAR(30) NOT NULL, reference VARCHAR(100), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor VARCHAR(80) NOT NULL, action VARCHAR(80) NOT NULL, target VARCHAR(120) NOT NULL, created_at DATETIME(6) NOT NULL);
